'use client';

// Reference component: this file establishes the pattern all components follow.
// - cva for variants, cn() for merging
// - semantic tokens only, via arbitrary-value classes bound to CSS vars
// - all states: hover, focus-visible (global ring), active, disabled, loading
// - min touch target 44px (A3)
// - cursor-pointer is explicit (A14): Tailwind v4's preflight sets buttons to
//   cursor: default, so every interactive component must opt back in

import * as React from 'react';
import { Slot, Slottable } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/cn';

const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 whitespace-nowrap select-none',
    'cursor-pointer rounded-[var(--radius-md)] font-medium',
    'transition-colors duration-[var(--duration-fast)]',
    'disabled:pointer-events-none disabled:cursor-not-allowed disabled:opacity-50',
    'min-h-[var(--touch-target-min)]',
    '[&_svg]:shrink-0',
  ],
  {
    variants: {
      variant: {
        primary: [
          'bg-[var(--color-action)] text-[var(--color-action-text)]',
          'hover:bg-[var(--color-action-hover)]',
          'active:opacity-90',
        ],
        secondary: [
          'bg-[var(--color-surface)] text-[var(--color-text-primary)]',
          'border border-[var(--color-border)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        ghost: [
          'text-[var(--color-text-primary)]',
          'hover:bg-[var(--color-surface-hover)]',
          'active:bg-[var(--color-surface-active)]',
        ],
        destructive: [
          'bg-[var(--color-status-error)] text-[var(--color-text-on-status)]',
          'hover:opacity-90 active:opacity-80',
        ],
      },
      size: {
        sm: 'h-9 min-h-9 px-3 text-[length:var(--text-sm)]',
        md: 'h-11 px-4 text-[length:var(--text-sm)]',
        lg: 'h-12 px-6 text-[length:var(--text-base)]',
        icon: 'h-11 w-11 p-0', // requires aria-label (A5)
      },
    },
    defaultVariants: { variant: 'primary', size: 'md' },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, loading = false, disabled, children, ...props }, ref) => {
    const Comp = asChild ? Slot : 'button';
    return (
      <Comp
        className={cn(buttonVariants({ variant, size }), className)}
        ref={ref}
        disabled={disabled || loading}
        aria-busy={loading || undefined}
        {...props}
      >
        {loading && (
          <span
            aria-hidden="true"
            className="size-4 animate-spin rounded-full border-2 border-current border-t-transparent"
          />
        )}
        {/* Slottable marks which child Slot merges into when asChild, so the
            loading sibling above no longer breaks the single-child rule. */}
        <Slottable>{children}</Slottable>
      </Comp>
    );
  }
);
Button.displayName = 'Button';

export { Button, buttonVariants };

import * as React from 'react';

import { ChevronLeft, ChevronRight, OverflowMenuHorizontal } from '@/components/base-ds-icons/pagination';
import { Button } from '@/components/ui/button';
import { cn } from '@/lib/cn';

function Pagination({ className, ...props }: React.ComponentProps<'nav'>) {
  return (
    <nav
      aria-label="Pagination"
      data-slot="pagination"
      className={cn('mx-auto flex w-full justify-center', className)}
      {...props}
    />
  );
}

function PaginationContent({ className, ...props }: React.ComponentProps<'ul'>) {
  return (
    <ul
      data-slot="pagination-content"
      className={cn('flex items-center gap-[var(--space-1)]', className)}
      {...props}
    />
  );
}

function PaginationItem(props: React.ComponentProps<'li'>) {
  return <li data-slot="pagination-item" {...props} />;
}

type PaginationLinkProps = {
  isActive?: boolean;
} & Pick<React.ComponentProps<typeof Button>, 'size'> &
  React.ComponentProps<'a'>;

function PaginationLink({ className, isActive, size = 'icon', ...props }: PaginationLinkProps) {
  return (
    <Button asChild variant={isActive ? 'secondary' : 'ghost'} size={size}>
      <a className={className} aria-current={isActive ? 'page' : undefined} data-slot="pagination-link" data-active={isActive} {...props} />
    </Button>
  );
}

function PaginationPrevious({ className, text = 'Previous', ...props }: React.ComponentProps<typeof PaginationLink> & { text?: string }) {
  return (
    <PaginationLink aria-label="Go to previous page" size="md" className={cn('gap-[var(--space-2)]', className)} {...props}>
      <ChevronLeft size={16} aria-hidden="true" />
      <span className="hidden sm:block">{text}</span>
    </PaginationLink>
  );
}

function PaginationNext({ className, text = 'Next', ...props }: React.ComponentProps<typeof PaginationLink> & { text?: string }) {
  return (
    <PaginationLink aria-label="Go to next page" size="md" className={cn('gap-[var(--space-2)]', className)} {...props}>
      <span className="hidden sm:block">{text}</span>
      <ChevronRight size={16} aria-hidden="true" />
    </PaginationLink>
  );
}

function PaginationEllipsis({ className, ...props }: React.ComponentProps<'span'>) {
  return (
    <span
      aria-hidden="true"
      data-slot="pagination-ellipsis"
      className={cn(
        'flex min-h-[var(--touch-target-min)] min-w-[var(--touch-target-min)] items-center justify-center',
        'text-[var(--color-text-tertiary)]',
        className
      )}
      {...props}
    >
      <OverflowMenuHorizontal size={16} aria-hidden="true" />
      <span className="sr-only">More pages</span>
    </span>
  );
}

export { Pagination, PaginationContent, PaginationEllipsis, PaginationItem, PaginationLink, PaginationNext, PaginationPrevious };

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
